    {

           using var activity =  StartCallActivity("GetMessagePublicForwardsAsync", typeof(GetMessagePublicForwards).FullName ?? "GetMessagePublicForwardsAsync");

           try
           {
             return client.GetMessagePublicForwardsAsync(chatId, messageId, offset, limit);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
